    #include <iostream>
#include <vector>
#include <queue>
using namespace std;

// Node Structure
class Node {
public:
    int data;
    Node* left, *right;
    Node (int x) {
        data = x;
        left = nullptr;
        right = nullptr;
    }
};

// function to serialize a tree.
vector<int> serialize(Node *root) {
    vector<int> arr;

    queue<Node*> q;
    q.push(root);

    while (!q.empty()) {
        Node* curr = q.front();
        q.pop();

        // If curr node is null,
        // append -1 to result.
        if (curr == nullptr) {
            arr.push_back(-1);
            continue;
        }

        // else push its value into
        // result and push left and right
        // child nodes into queue.
        arr.push_back(curr->data);

        q.push(curr->left);
        q.push(curr->right);
    }

    return arr;
}


//  function to deserialize a tree.
Node * deSerialize(vector<int> &arr) {

   if (arr[0]==-1) return nullptr;

   // create root node and push 
   // it into queue
   Node* root = new Node(arr[0]);
   queue<Node*> q;
   q.push(root);

   int i = 1;
   while (!q.empty()) {
       Node* curr = q.front();
       q.pop();

       // If left node is not null
       if (arr[i]!=-1) {
           Node* left = new Node(arr[i]);
           curr->left = left;
           q.push(left);
       }
       i++;

       // If right node is not null
       if (arr[i]!=-1) {
           Node* right = new Node(arr[i]);
           curr->right = right;
           q.push(right);
       }
       i++;
   }

   return root;
}


